tests:
test({ sr: 'ime i prezime bez srednjeg imena', en: 'first and last name without a middle name' }, () => {
  expect(getFullName({ firstName: 'Ana', lastName: 'Petrovic' })).toBe('Ana Petrovic');
});
test({ sr: 'srednje ime ide između', en: 'the middle name goes between' }, () => {
  expect(getFullName({ firstName: 'Ana', middleName: 'Maria', lastName: 'Petrovic' })).toBe('Ana Maria Petrovic');
});
test({ sr: 'prazno srednje ime se preskače', en: 'an empty middle name is skipped' }, () => {
  expect(getFullName({ firstName: 'Ana', middleName: '', lastName: 'Petrovic' })).toBe('Ana Petrovic');
});

hiddenTests:
test('other properties are ignored', () => {
  expect(getFullName({ firstName: 'Ana', lastName: 'Petrovic', age: 30 })).toBe('Ana Petrovic');
  expect(getFullName({ age: 30, firstName: 'Ana', middleName: 'Maria', lastName: 'Petrovic' })).toBe('Ana Maria Petrovic');
});
test('different names', () => {
  expect(getFullName({ firstName: 'Jo', middleName: 'K', lastName: 'Li' })).toBe('Jo K Li');
});
test('no double space and no spaces at the ends', () => {
  const name = getFullName({ firstName: 'Ana', middleName: '', lastName: 'Petrovic' });
  expect(name).not.toContain('  ');
  expect(name).toHaveLength(12);
});
test('does not change the object', () => {
  const person = { firstName: 'Ana', middleName: 'Maria', lastName: 'Petrovic' };
  getFullName(person);
  expect(person).toEqual({ firstName: 'Ana', middleName: 'Maria', lastName: 'Petrovic' });
});
test('the word undefined never appears in the result', () => {
  expect(getFullName({ firstName: 'Ana', lastName: 'Petrovic' })).not.toContain('undefined');
});

